  'admin.peopleImportMapping.modeBoundary': '18개 항목 모두 원본 열을 사용하거나 비워 둘 수 있어요. 닫힌 열거형 항목 6개만 상수를 사용할 수 있고, 이 항목의 원본 값에는 명시적인 번역이 필요해요.',
